from qiskit import QuantumCircuit, ClassicalRegister, QuantumRegister,transpile
from qiskit_aer import AerSimulator

from qiskit.visualization import plot_histogram

from math import pi
import numpy as np
import matplotlib.pyplot as plt

from qiskit.transpiler import PassManager
from qiskit.transpiler.passes import UnrollCustomDefinitions, BasisTranslator
from qiskit.circuit.equivalence_library import SessionEquivalenceLibrary as SEL

def unroll_circuit(qc):

  # Translate circuit to 'u' and 'cx' basis
  target_basis = ['u', 'cx']

  pm = PassManager([
      UnrollCustomDefinitions(SEL, target_basis),
      BasisTranslator(SEL, target_basis)
  ])

  unrolled = pm.run(qc)

  return unrolled

def circuit_cost(qc):

    unrolled = unroll_circuit(qc)

    # Count operations
    ops = unrolled.count_ops()
    num_u  = ops.get('u', 0)
    num_cx = ops.get('cx', 0)

    # Define a simple cost model
    total_cost = num_u + num_cx * 10

    # Print summary
    print(f"Total cost: {total_cost} (u: {num_u}, cx: {num_cx})")

"""## **A Helper Function**
The following is a helper function to check whether a solution is correct
"""

def toggle_matrix():
    T = [[0]*9 for _ in range(9)]
    neighbors = {
        0: [0,1,3],
        1: [1,0,2,4],
        2: [2,1,5],
        3: [3,0,4,6],
        4: [4,1,3,5,7],
        5: [5,2,4,8],
        6: [6,3,7],
        7: [7,4,6,8],
        8: [8,5,7]
    }
    for i, adj in neighbors.items():
        for j in adj:
            T[j][i] = 1
    return T


def check_lights_out(initial, flips):
    T = toggle_matrix()
    final = [(initial[i] + sum(T[i][j]*flips[j] for j in range(9)) % 2) % 2 for i in range(9)]
    solved = all(v == 0 for v in final)

    print(f"Initial : {initial}")
    print(f"Flips   : {flips}")
    print(f"Final   : {final}")
    print("Result  :", "Lights out ✅" if solved else "Not solved ❌")

