flips = [1, 1, 0, 0, 1, 0, 1, 0, 1]

check_lights_out(input, flips)

"""## **Challenge**: Grover’s Algorithm for *Lights Out* (3×3)

Your task is to use **Grover's algorithm** to find the solution to a *Lights Out* puzzle from a given starting position.

- Write a function `lightsOut(input)` that **takes the starting position** (a 9-bit list for a 3×3 grid, left→right, top→bottom) and **returns the full circuit (including measurements)**.
- Run the **Grover iteration 4 times**.
- The **classical readout** must report the solution **in the same left→right order**.

Your code will be tested using the cells at the end of the notebook. We will **only check the most frequent result**, and your circuit will be tested on **multiple inputs** to verify correctness.


"""

# lights_out_grover.py
# Quantum Lights Out Puzzle using Grover's Algorithm (3x3)
# Requires: qiskit, qiskit-aer, matplotlib, numpy
h = -1

mode = 'v-chain'

# === Helper: Multi-controlled Z via mcp(pi) if available, else H–MCX–H ===
def mcz(qc: QuantumCircuit, qubits,q_ancilla):

    controls = list(qubits[:-1])
    target   = qubits[-1]


    qc.h(target)
    qc.mcx(controls, target,q_ancilla,mode=mode)
    qc.h(target)

# --- Initialization of press decisions ---
def init_presses(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n, name="init")
    qc.h(range(n))   # superposition over press patterns
    return qc

# --- Diffusion operator over press register only ---
def diffusion(n: int) -> QuantumCircuit:
    n_qubit = QuantumRegister(n, 'qubit')
    qc = QuantumCircuit(n_qubit, name="diffusion")

    qc.u(-pi/2, pi, pi, range(n))

    match mode:
        case 'basic' | 'v-chain' | 'v-chain-dirty':
            q_ancilla = QuantumRegister(n - 2, 'ancilla')
        case 'recursion':
            q_ancilla = QuantumRegister(1, 'ancilla')
        case 'noancilla':
            q_ancilla = []

    qc.add_register(q_ancilla)

    mcz(qc,n_qubit,q_ancilla)

    qc.u(pi/2, pi, pi, range(n))

    return qc



# --- Build adjacency matrix for 3x3 Lights Out ---
def idx(r, c):    # map (row,col) to index 0..8
    return 3*r + c

def neighbors_3x3(r, c):
    N = [(r, c)]
    if r > 0: N.append((r-1, c))
    if r < 2: N.append((r+1, c))
    if c > 0: N.append((r, c-1))
    if c < 2: N.append((r, c+1))
    return N

def build_A_3x3():   # 9x9 matrix over GF(2)
    A = np.zeros((9, 9), dtype=int)
    for r in range(3):
        for c in range(3):
            j = idx(r, c)  # affected cell index
            for (rr, cc) in neighbors_3x3(r, c):
                i = idx(rr, cc)   # press at i toggles j
                A[j, i] ^= 1
    return A

A_3x3 = build_A_3x3()

# --- Lights Out Oracle (clean ancilla: uncomputed) ---
def lights_out_oracle(s0_bits: str) -> QuantumCircuit:

    assert len(s0_bits) == 9

    n = 9

    presses = QuantumRegister(n, 'p')   # press decisions
    anc     = QuantumRegister(n, 'y')   # y = s0 XOR A p
    qc = QuantumCircuit(presses, anc, name="oracle_lights")

    match mode:
      case 'basic' | 'v-chain' | 'v-chain-dirty':
          q_ancilla = QuantumRegister(n - 2, 'ancilla')
      case 'recursion':
          q_ancilla = QuantumRegister(1, 'ancilla')
      case 'noancilla':
          q_ancilla = []

    qc.add_register(q_ancilla)
    if h != 0:
      # ---- zero activation z gate
      # (3) mark y==0  (flip all anc -> MCZ -> flip back)
      for j in range(9):
        qc.x(anc[j])
      mcz(qc, anc,q_ancilla)       # phase flip if all anc==1  (i.e., y==0)
      for j in range(9):
        qc.x(anc[j])

    # (4) Uncompute anc -> |0>
    for j in range(9):
        for i in range(9):
            if A_3x3[j, i] == 1:
                qc.cx(presses[i], anc[j])

    for j, b in enumerate(reversed(s0_bits)):
        if b == "1":
            qc.x(anc[j])

    return qc

# --- Full Grover circuit for 3x3 Lights Out ---
def full_grover_lights_3x3(s0_bits: str, k: int):
    global h
    assert len(s0_bits) == 9

    n = 9
    p = QuantumRegister(n, 'p')
    y = QuantumRegister(n, 'y')  # ancillas for the oracle

    n_controls = n - 1

    match mode:
        case 'basic' | 'v-chain' | 'v-chain-dirty':
            q_ancilla = QuantumRegister(n - 2, 'ancilla')
        case 'recursion':
            q_ancilla = QuantumRegister(1, 'ancilla')
        case 'noancilla':
            q_ancilla = []

    c = ClassicalRegister(n, 'c')
    qc = QuantumCircuit(p, y, c, name="LightsOut_Grover")
    qc.add_register(q_ancilla)


    # init: superposition on press decisions
    qc.compose(init_presses(n), qubits=p, inplace=True)
    qc.barrier()
    # Grover iterations: (oracle + diffusion) on p only
    for _ in range(k):
        h = _
        qc.compose(lights_out_oracle(s0_bits), qubits=[*p, *y,*q_ancilla], inplace=True)
        qc.barrier()
        qc.compose(diffusion(n), qubits=[*p,*q_ancilla], inplace=True)
        qc.barrier()
    qc.measure(p[::-1], c)

    return qc

def solution(input):
    s0 = input
    k  = 4
    circ = full_grover_lights_3x3(s0, k)

    return circ

def lightsOut(input):

    return solution("".join([str(i)for i in input]))

input = [0, 1, 1, 1, 0, 0, 1, 1, 1]

circuit = lightsOut(input)

circuit.draw('mpl', fold=-1)

input = [1, 1, 0, 1,0,0,0,0,0]

circuit = lightsOut(input)

backend = AerSimulator()

unrolled_circuit = unroll_circuit(circuit)

job = backend.run(unrolled_circuit, shots=1000)
result = job.result()
count = result.get_counts()

flips = max(count,key=count.get)[::-1] # reverse the order of the bits
flips = [int(b) for b in flips]

check_lights_out(input, flips)

# h variable
circuit_cost(circuit)

# v-chain
circuit_cost(circuit)

# v-chain-dirty
circuit_cost(circuit)

# basic
circuit_cost(circuit)

