optimized = transpile(decomposed, backend, optimization_level=3)

print("Optimized circuit depth:", optimized.depth())

# 3️⃣ Compare cost before and after optimization
print("\n🔹 Cost before optimization:")
circuit_cost(circuit)

print("\n🔹 Cost after optimization:")
circuit_cost(optimized)

